#include <Arduino.h>
const int LED = 2;
unsigned long last = 0;
bool on = false;
void setup() {
  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  Serial.println("PlatformIO ESP32 up");
}
void loop() {
  if (millis() - last >= 500) {
    last = millis();
    on = !on;
    digitalWrite(LED, on);
    Serial.println(on ? "on" : "off");
  }
}
